#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up one CodeSync application server, with running code turned off.
# Run on the server, from the repository root:  sudo bash infra/deploy/setup-server.sh
# Safe to re-run. It keeps every value already in .env.prod.

TOTAL_STAGES=9
ENV_FILE=".env.prod"
COMPOSE=(docker compose -f infra/compose/docker-compose.prod.yml --env-file "$ENV_FILE")

secret_once() {
  local key="$1"
  if [[ -n "$(_existing "$key" || true)" ]]; then
    note "$key is already set, keeping it"
  else
    write_env "$key" "$(openssl rand -hex 32)"
  fi
}

if [[ "$(id -u)" -ne 0 ]]; then
  printf 'Run this with sudo: sudo bash infra/deploy/setup-server.sh\n' >&2
  exit 1
fi
if [[ ! -f infra/compose/docker-compose.prod.yml ]]; then
  printf 'Run this from the root of the CodeSync repository.\n' >&2
  exit 1
fi

banner "CodeSync server setup"

stage "Domain"
say "Your domain must point at this server before a certificate can be issued."
SERVER_IP=$(curl -4fsS https://api.ipify.org || true)
say "This server's public address is: ${SERVER_IP:-unknown}"
step "At your DNS provider, add an A record for your domain pointing at that address."
ask DOMAIN "Domain for CodeSync (for example code.example.edu):"
write_env DOMAIN "$DOMAIN"
write_env PUBLIC_WEB_URL "https://$DOMAIN"
write_env PUBLIC_API_URL "https://$DOMAIN"
RESOLVED=$(getent ahostsv4 "$DOMAIN" | awk 'NR==1 {print $1}' || true)
if [[ "$RESOLVED" == "$SERVER_IP" ]]; then
  say "DNS is correct: $DOMAIN points here."
else
  warn "$DOMAIN points at '${RESOLVED:-nothing}', not ${SERVER_IP:-this server}."
  note "DNS can take a while to update. The certificate stage fails until this is right."
fi
pause "Press Enter to continue"

stage "Docker and Certbot"
if command -v docker >/dev/null 2>&1 && docker compose version >/dev/null 2>&1; then
  say "Docker and Compose are already installed."
elif confirm "Install Docker from get.docker.com?"; then
  curl -fsSL https://get.docker.com | sh
else
  SKIPPED+=("Install Docker with the Compose plugin")
fi
if ! command -v certbot >/dev/null 2>&1; then
  if confirm "Install Certbot with apt?"; then
    apt-get update -qq
    apt-get install -y -qq certbot
  else
    SKIPPED+=("Install Certbot")
  fi
fi
pause "Press Enter to continue"

stage "Firewall"
say "Only SSH, HTTP and HTTPS need to be open."
warn "If your SSH port is not 22, stop here and allow it first, or you will lock yourself out."
if command -v ufw >/dev/null 2>&1 && confirm "Allow ports 22, 80 and 443, and enable ufw?"; then
  ufw allow 22/tcp
  ufw allow 80/tcp
  ufw allow 443/tcp
  ufw --force enable
else
  note "Skipped. Check that your provider's firewall allows ports 80 and 443."
fi
pause "Press Enter to continue"

stage "Secrets"
say "Generating random secrets. They stay on this server, in $ENV_FILE."
for key in POSTGRES_PASSWORD REDIS_PASSWORD GRAFANA_PASSWORD ACCESS_TOKEN_SECRET \
  COLLAB_TOKEN_SECRET INVITE_TOKEN_SECRET OAUTH_STATE_SECRET INTERNAL_SERVICE_TOKEN; do
  secret_once "$key"
done
chmod 600 "$ENV_FILE"
pause "Press Enter to continue"

stage "Outgoing email"
say "New accounts verify by email, so without this nobody can finish signing up."
step "Get SMTP details from any mail provider you already use or sign up for."
note "Format: smtp://USER:PASSWORD@HOST:587"
note "Percent-encode special characters in the password, and avoid \$ in it."
ask_secret SMTP_URL "SMTP URL:"
ask MAIL_FROM "From address (for example CodeSync <no-reply@$DOMAIN>):"
write_env SMTP_URL "$SMTP_URL"
write_env MAIL_FROM "$MAIL_FROM"
pause "Press Enter to continue"

stage "GitHub sign-in (optional)"
if confirm "Set up Sign in with GitHub now?"; then
  open_url "https://github.com/settings/developers"
  step "Click New OAuth App."
  step "Homepage URL: https://$DOMAIN"
  step "Authorization callback URL: https://$DOMAIN/api/v1/auth/oauth/github/callback"
  step "Register it, then click Generate a new client secret."
  ask GITHUB_CLIENT_ID "Client ID:"
  ask_secret GITHUB_CLIENT_SECRET "Client secret:"
  write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
  write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"
else
  note "Skipped. The GitHub button stays on the sign-in page but will not work."
fi
pause "Press Enter to continue"

stage "Container images"
say "Prebuilt images are best. Building the web app here can run a small server out of memory."
step "After CI has passed on GitHub, the prefix is ghcr.io/<owner>/<repo>, all lower case."
note "Leave it blank to build on this server instead, which needs about 4 GB of memory."
ask IMAGE_PREFIX "Image prefix:"
write_env IMAGE_PREFIX "$IMAGE_PREFIX"
write_env IMAGE_TAG "latest"
if [[ -n "$IMAGE_PREFIX" ]] && confirm "Is the GitHub repository private?"; then
  open_url "https://github.com/settings/tokens"
  step "Create a classic token with only the read:packages scope."
  ask GHCR_USER "GitHub username:"
  ask_secret GHCR_TOKEN "Token:"
  printf '%s' "$GHCR_TOKEN" | docker login ghcr.io -u "$GHCR_USER" --password-stdin
fi
pause "Press Enter to continue"

stage "HTTPS certificate"
say "Asks Let's Encrypt for a certificate. Port 80 must be free and DNS must be correct."
mkdir -p /var/www/certbot
if [[ -d "/etc/letsencrypt/live/$DOMAIN" ]]; then
  say "A certificate for $DOMAIN already exists."
else
  ask CERT_EMAIL "Email for certificate expiry notices:"
  certbot certonly --standalone --non-interactive --agree-tos -m "$CERT_EMAIL" -d "$DOMAIN"
fi
mkdir -p /etc/letsencrypt/renewal-hooks/deploy
cat > /etc/letsencrypt/renewal-hooks/deploy/reload-nginx.sh <<'HOOK'
#!/bin/sh
docker exec codesync-nginx-1 nginx -s reload
HOOK
chmod +x /etc/letsencrypt/renewal-hooks/deploy/reload-nginx.sh
pause "Press Enter to continue"

stage "Start CodeSync"
say "This pulls or builds the images, applies database migrations and starts everything."
if confirm "Start CodeSync now?"; then
  if [[ -n "$IMAGE_PREFIX" ]]; then
    "${COMPOSE[@]}" pull
    "${COMPOSE[@]}" up -d --no-build
  else
    "${COMPOSE[@]}" up -d --build
  fi
  say "Waiting for the site to answer..."
  STATUS="000"
  for _ in $(seq 1 30); do
    STATUS=$(curl -s -o /dev/null -w '%{http_code}' "https://$DOMAIN/api/v1/me" || true)
    [[ "$STATUS" == "401" ]] && break
    sleep 5
  done
  if [[ "$STATUS" == "401" ]]; then
    say "CodeSync is live at https://$DOMAIN"
    # Renewals answer through Nginx from now on, so they need no downtime.
    certbot reconfigure --cert-name "$DOMAIN" --webroot --webroot-path /var/www/certbot \
      --non-interactive || SKIPPED+=("Switch renewal to webroot, see docs/deployment.md")
  else
    warn "The API did not answer. Last status: $STATUS"
    note "See what happened with: ${COMPOSE[*]} logs --tail 50"
    SKIPPED+=("Fix start-up, then re-run this wizard")
  fi
else
  SKIPPED+=("Start CodeSync: ${COMPOSE[*]} up -d")
fi
pause "Press Enter to finish"

finish
note "Running code stays off until a separate executor host exists. See docs/deployment.md."
